composeOverride:
# Generated by McHarbor App Store
services:
  {{serviceName}}:
    image: {{image}}
    container_name: {{containerName}}
    restart: unless-stopped
{{ports}}
    environment:
      TZ: {{env.TZ}}
      DATABASE_URL: "postgres://conjur:{{env.POSTGRES_PASSWORD}}@{{serviceName}}-postgres/conjur"
      POSTGRES_PASSWORD: {{env.POSTGRES_PASSWORD}}
      CONJUR_DATA_KEY: {{env.CONJUR_DATA_KEY}}
      CONJUR_ACCOUNT: {{env.CONJUR_ACCOUNT}}
    depends_on:
      - {{serviceName}}-postgres
  {{serviceName}}-postgres:
    image: postgres:16-alpine
    container_name: {{serviceName}}-postgres
    restart: unless-stopped
    environment:
      POSTGRES_USER: conjur
      POSTGRES_PASSWORD: {{env.POSTGRES_PASSWORD}}
      POSTGRES_DB: conjur
    volumes:
      - {{appDataPath}}/postgres:/var/lib/postgresql/data
